changeSet.sql:
CREATE TABLE lib_shamela_category (
    id            BIGINT PRIMARY KEY,
    name          TEXT NOT NULL,
    display_order INTEGER,
    deleted_at    TIMESTAMPTZ
);

CREATE TABLE lib_shamela_author (
    id          BIGINT PRIMARY KEY,
    name        TEXT NOT NULL,
    biography   TEXT,
    death_year  INTEGER,
    deleted_at  TIMESTAMPTZ
);

CREATE TABLE lib_shamela_book (
    id                BIGINT PRIMARY KEY,
    name              TEXT NOT NULL,
    category_id       BIGINT REFERENCES lib_shamela_category(id) ON DELETE SET NULL,
    author_id         BIGINT REFERENCES lib_shamela_author(id) ON DELETE SET NULL,
    type              SMALLINT,
    publication_year  INTEGER,
    is_printed        BOOLEAN,
    major_release     INTEGER NOT NULL,
    minor_release     INTEGER NOT NULL,
    bibliography      TEXT,
    hint              TEXT,
    pdf_links         JSONB,
    extra_metadata    JSONB,
    imported_at       TIMESTAMPTZ,
    deleted_at        TIMESTAMPTZ
);
CREATE INDEX idx_lib_shamela_book_category    ON lib_shamela_book(category_id);
CREATE INDEX idx_lib_shamela_book_author      ON lib_shamela_book(author_id);
CREATE INDEX idx_lib_shamela_book_pdf_gin     ON lib_shamela_book USING GIN (pdf_links);
CREATE INDEX idx_lib_shamela_book_imported_at ON lib_shamela_book(imported_at);

CREATE TABLE lib_shamela_page (
    book_id       BIGINT NOT NULL REFERENCES lib_shamela_book(id) ON DELETE CASCADE,
    id            INTEGER NOT NULL,
    content       TEXT NOT NULL,
    part          TEXT,
    printed_page  TEXT,
    number        TEXT,
    services      TEXT,
    PRIMARY KEY (book_id, id)
);

CREATE TABLE lib_shamela_title (
    book_id    BIGINT NOT NULL REFERENCES lib_shamela_book(id) ON DELETE CASCADE,
    id         INTEGER NOT NULL,
    content    TEXT NOT NULL,
    page_ref   TEXT,
    parent_id  INTEGER,
    PRIMARY KEY (book_id, id)
);
CREATE INDEX idx_lib_shamela_title_parent ON lib_shamela_title(book_id, parent_id);

CREATE TABLE lib_shamela_sync_state (
    id              SMALLINT PRIMARY KEY DEFAULT 1 CHECK (id = 1),
    master_version  INTEGER NOT NULL DEFAULT 0,
    last_synced_at  TIMESTAMPTZ
);
INSERT INTO lib_shamela_sync_state (id) VALUES (1);

rollback.sql:
DROP TABLE lib_shamela_sync_state;
DROP TABLE lib_shamela_title;
DROP TABLE lib_shamela_page;
DROP TABLE lib_shamela_book;
DROP TABLE lib_shamela_author;
DROP TABLE lib_shamela_category;
